import glob, re, os

ws = "/home/nimrod_rotem/patent-search-pilot/data/draft_workspaces/p9"
tab = {}
for line in open(os.path.join(ws, "draft/numerals.md")):
    m = re.match(r"\|\s*(\d+)\s*\|\s*(.+?)\s*\|", line)
    if m:
        tab[m.group(1)] = m.group(2)

used = {}
for f in sorted(glob.glob(os.path.join(ws, "figures/*.md"))):
    txt = open(f).read()
    body, _, nums = txt.partition("## Numerals")
    listed = re.findall(r"^-\s*(\d+)\s", nums, re.M)
    inbody = set(re.findall(r"\b(\d{2,3})\b", body))
    name = os.path.basename(f)
    print(name, "total", len(txt), "brief", len(body.strip()), "listed", listed)
    stray = inbody - set(listed) - {"1", "2", "3", "4", "5", "6"}
    if stray:
        print("   numerals in prose not listed:", sorted(stray))
    for n in listed:
        used.setdefault(n, []).append(name)

print()
missing = [n for n in tab if n not in used]
print("table numerals not on any sheet:", missing)
print("listed numerals not in table:", [n for n in used if n not in tab])

